144	static void *ingest_thread_main(void *arg)
145	{
146	    ingestion_ctx_t *ctx = arg;
147	    unsigned backoff_attempt = 0;
148	
149	#ifdef HAVE_LIBCURL
150	    CURLcode cr;
151	    if (ctx->source.type == SRC_HTTP) {
152	        curl_global_init(CURL_GLOBAL_ALL);
153	    }
154	#endif
155	
156	    while (!ctx->should_stop) {
157	        if (ingest_open_source(&ctx->source) != 0) {
158	            /* open failed, wait and retry with back-off */
159	            backoff_sleep(&backoff_attempt);
160	            continue;
161	        }
162	        backoff_attempt = 0; /* reset on success */
163	
164	        char buf[INGEST_BUF_SZ];
165	        size_t len = 0;
166	
167	        /* two code paths: FILE* or CURL streaming */
168	        if (ctx->source.type == SRC_HTTP) {
169	#ifdef HAVE_LIBCURL
170	            /* For HTTP streaming, libcurl will push data to our callback which will in turn
171	             * publish events. Here we just perform() until it returns or stop requested. */
172	            CURL *curl = ctx->source.handle.curl;
173	            while (!ctx->should_stop &&
174	                   (cr = curl_easy_perform(curl)) == CURLE_OK) {
175	                /* libcurl will keep calling http_write_cb. We loop until stop or error. */
176	            }
177	            if (cr != CURLE_OK && !ctx->should_stop) {
178	                LOGW("ingestion: curl_easy_perform stopped: %s", curl_easy_strerror(cr));
179	            }
180	#endif
181	        } else { /* FILE or STDIN */
182	            FILE *fp = ctx->source.handle.fp;
183	            while (!ctx->should_stop && fgets(buf, sizeof(buf), fp) != NULL) {
184	                len = strnlen(buf, sizeof(buf));
185	                if (publish_line(buf, len, ctx) != 0) {
186	                    /* publish failed; count but keep going */
187	                    metrics_counter_inc(ctx->m_records_err);
188	                } else {
189	                    metrics_counter_inc(ctx->m_records_ok);
190	                }
191	            }
192	
193	            if (!ctx->should_stop && ferror(fp)) {
194	                LOGW("ingestion: read error on %s: %s",
195	                     ctx->source.identifier, strerror(errno));
196	            }
197	        }
198	
199	        ingest_close_source(&ctx->source);
200	
201	        if (!ctx->should_stop) {
202	            /* auto-reconnect after short delay */
203	            LOGI("ingestion: reconnecting to %s", ctx->source.identifier);
204	            backoff_sleep(&backoff_attempt);
205	        }
206	    }
207	
208	#ifdef HAVE_LIBCURL
209	    if (ctx->source.type == SRC_HTTP) {
210	        curl_global_cleanup();
211	    }
212	#endif
213	
214	    return NULL;
215	}
