221	static int ingest_open_source(ingest_source_t *src)
222	{
223	    switch (src->type) {
224	        case SRC_STDIN:
225	            src->handle.fp = stdin;
226	            return 0;
227	        case SRC_FILE:
228	            src->handle.fp = fopen(src->identifier, "r");
229	            if (!src->handle.fp) {
230	                LOGE("ingestion: unable to open file '%s': %s",
231	                     src->identifier, strerror(errno));
232	                return -1;
233	            }
234	            return 0;
235	        case SRC_HTTP:
236	#ifdef HAVE_LIBCURL
237	        {
238	            CURL *c = curl_easy_init();
239	            if (!c) {
240	                LOGE("ingestion: curl_easy_init failed");
241	                return -1;
242	            }
243	
244	            curl_easy_setopt(c, CURLOPT_URL, src->identifier);
245	            curl_easy_setopt(c, CURLOPT_WRITEFUNCTION, http_write_cb);
246	            curl_easy_setopt(c, CURLOPT_WRITEDATA, src);
247	            curl_easy_setopt(c, CURLOPT_USERAGENT, "StreamScoop/" VERSION_STRING);
248	            curl_easy_setopt(c, CURLOPT_FAILONERROR, 1L);
249	            curl_easy_setopt(c, CURLOPT_CONNECTTIMEOUT, 5L);
250	            curl_easy_setopt(c, CURLOPT_TCP_KEEPALIVE, 1L);
251	
252	            src->handle.curl = c;
253	            return 0;
254	        }
255	#else
256	            LOGE("ingestion: built without libcurl support");
257	            return -1;
258	#endif
259	        default:
260	            return -1;
261	    }
262	}
263	
264	static void ingest_close_source(ingest_source_t *src)
265	{
266	    switch (src->type) {
267	        case SRC_STDIN:
268	            /* nothing */
269	            break;
270	        case SRC_FILE:
271	            if (src->handle.fp) {
272	                fclose(src->handle.fp);
273	                src->handle.fp = NULL;
274	            }
275	            break;
276	        case SRC_HTTP:
277	#ifdef HAVE_LIBCURL
278	            if (src->handle.curl) {
279	                curl_easy_cleanup(src->handle.curl);
280	                src->handle.curl = NULL;
281	            }
282	#endif
283	            break;
284	        default:
285	            break;
286	    }
287	}
