334	/* push a single line onto the bus */
335	static int publish_line(const char *line, size_t len, ingestion_ctx_t *ctx)
336	{
337	    if (!line || len == 0) return -1;
338	
339	    ingest_event_t ev = {
340	        .seq_no        = ctx->seq_no++,
341	        .capture_us    = now_epoch_us(),
342	        .payload_len   = (uint32_t)len,
343	        .payload       = (const uint8_t *)line
344	    };
345	
346	    return event_bus_publish(EV_INGEST_RECORD, &ev, sizeof(ev));
347	}
348	
349	/* high-resolution timestamp helper */
350	static uint64_t now_epoch_us(void)
351	{
352	    struct timespec ts;
353	#if defined(CLOCK_REALTIME_COARSE)
354	    clock_gettime(CLOCK_REALTIME_COARSE, &ts);
355	#else
356	    clock_gettime(CLOCK_REALTIME, &ts);
357	#endif
358	    return (uint64_t)ts.tv_sec * 1000000ULL + ts.tv_nsec / 1000ULL;
359	}
