361	/* Simple exponential back-off with jitter */
362	static void backoff_sleep(unsigned *attempt)
363	{
364	    if (*attempt < 10) (*attempt)++;
365	    unsigned delay_ms = RECONNECT_BASE_MS * (1U << (*attempt));
366	    if (delay_ms > RECONNECT_MAX_MS)
367	        delay_ms = RECONNECT_MAX_MS;
368	
369	    /* Add 0-250ms jitter */
370	    delay_ms += rand() % 250;
371	
372	    LOGI("ingestion: sleeping for %u ms before retry", delay_ms);
373	    usleep(delay_ms * 1000);
374	}
