129	static void bus_init(event_bus_t *bus) {
130	    for (int i = 0; i < EVT__COUNT; ++i) {
131	        bus->topics[i].sub_count = 0;
132	        pthread_mutex_init(&bus->topics[i].mtx, NULL);
133	    }
134	}
135	
136	static void bus_subscribe(event_bus_t *bus, evt_type_t evt, subscriber_cb cb, void *ctx) {
137	    topic_t *tp = &bus->topics[evt];
138	    pthread_mutex_lock(&tp->mtx);
139	    if (tp->sub_count >= BUS_MAX_SUBS_PER_EVENT) {
140	        fprintf(stderr, "Too many subscribers for event %d\n", evt);
141	        exit(EXIT_FAILURE);
142	    }
143	    tp->subscribers[tp->sub_count++] = (subscriber_t){.cb = cb, .ctx = ctx};
144	    pthread_mutex_unlock(&tp->mtx);
145	}
146	
147	static void bus_publish(event_bus_t *bus, const event_t *ev) {
148	    topic_t *tp = &bus->topics[ev->type];
149	    pthread_mutex_lock(&tp->mtx);
150	    for (size_t i = 0; i < tp->sub_count; ++i) {
151	        tp->subscribers[i].cb(ev, tp->subscribers[i].ctx);
152	    }
153	    pthread_mutex_unlock(&tp->mtx);
154	}
