163	static void validator_cb(const event_t *ev, void *ctx_void) {
164	    validator_ctx_t *ctx = ctx_void;
165	    if (ev->type != EVT_RECORD_INGESTED) return;
166	
167	    record_t *rec = ev->record;
168	    bool ok = rec->field_count == ctx->app->schema.field_count;
169	
170	    event_t next = {
171	        .type   = ok ? EVT_VALID_RECORD : EVT_INVALID_RECORD,
172	        .record = rec
173	    };
174	    bus_publish(&ctx->app->bus, &next);
175	}
