217	static void storage_cb(const event_t *ev, void *ctx_void) {
218	    if (ev->type != EVT_TRANSFORMED_RECORD) return;
219	    storage_ctx_t *st = ctx_void;
220	    record_t *r = ev->record;
221	
222	    sqlite3_stmt *stmt = st->stmt_insert;
223	    sqlite3_reset(stmt);
224	    char ts[32];
225	    sqlite3_bind_text(stmt, 1, now_utc_iso(ts), -1, SQLITE_TRANSIENT);
226	
227	    /* Bind up to 5 fields max for demo */
228	    for (int i = 0; i < 5; ++i) {
229	        if (i < r->field_count)
230	            sqlite3_bind_text(stmt, 2 + i, r->fields[i], -1, SQLITE_TRANSIENT);
231	        else
232	            sqlite3_bind_null(stmt, 2 + i);
233	    }
234	
235	    if (sqlite3_step(stmt) != SQLITE_DONE) {
236	        fprintf(stderr, "SQLite insert failed: %s\n", sqlite3_errmsg(st->app->db));
237	    }
238	}
