314	/* ───────────────────────────────────────────
315	 * Schema loader – simple CSV header list
316	 * ─────────────────────────────────────────── */
317	static void schema_load(const char *path, schema_t *schema) {
318	    FILE *fp = fopen(path, "r");
319	    if (!fp) fatal("fopen schema");
320	
321	    char buf[512];
322	    if (!fgets(buf, sizeof buf, fp)) fatal("schema empty");
323	
324	    char *nl = strchr(buf, '\n');
325	    if (nl) *nl = '\0';
326	
327	    schema->field_count = parse_csv_line(buf, (char **)schema->fields, SCHEMA_MAX_FIELDS);
328	    fclose(fp);
329	}
