1	/*
2	 * processing.c
3	 *
4	 * StreamScoop Utility Lake – processing layer
5	 *
6	 * The processing layer validates, transforms, stores, and broadcasts events
7	 * for each incoming stream record.  It implements a simple observer pattern
8	 * so that other components (dashboard, metrics, etc.) can subscribe to the
9	 * pipeline without tight coupling.
