429	static void free_record(record_t *rec)
430	{
431	    if (!rec || !rec->fields) return;
432	    for (size_t i = 0; i < rec->field_count; ++i) free(rec->fields[i]);
433	    free(rec->fields);
434	    rec->fields = NULL;
