438	/* **********************************************************************
439	 *                         Validation
440	 * *********************************************************************/
441	
442	static bool validate_int(const char *s)
443	{
444	    if (!s || !*s) return false;
445	    if (*s == '+' || *s == '-') s++;
446	    while (*s && isdigit((unsigned char)*s)) s++;
447	    return *s == '\0';
448	}
449	
450	static bool validate_float(const char *s)
451	{
452	    if (!s || !*s) return false;
453	    char *end = NULL;
454	    strtod(s, &end);
455	    return end && *end == '\0';
456	}
457	
458	static bool validate_bool(const char *s)
459	{
460	    return s && (strcasecmp(s, "true") == 0 ||
461	                 strcasecmp(s, "false") == 0 ||
462	                 strcmp(s, "0") == 0 ||
463	                 strcmp(s, "1") == 0);
464	}
465	
466	static bool validate_record(const record_t *rec, const schema_t *s, char **err_out)
467	{
468	    *err_out = NULL;
469	    if (rec->field_count != s->count) {
470	        asprintf(err_out, "Field count mismatch: expected %zu, got %zu",
471	                 s->count, rec->field_count);
472	        return false;
473	    }
474	
475	    for (size_t i = 0; i < s->count; ++i) {
476	        const char *val = rec->fields[i];
477	        switch (s->fields[i].type) {
478	            case FIELD_STRING:
479	                /* always valid */
480	                break;
481	            case FIELD_INT:
482	                if (!validate_int(val)) {
483	                    asprintf(err_out, "Field '%s' value '%s' not int",
484	                             s->fields[i].name, val);
485	                    return false;
486	                }
487	                break;
488	            case FIELD_FLOAT:
489	                if (!validate_float(val)) {
490	                    asprintf(err_out, "Field '%s' value '%s' not float",
491	                             s->fields[i].name, val);
492	                    return false;
493	                }
494	                break;
495	            case FIELD_BOOL:
496	                if (!validate_bool(val)) {
497	                    asprintf(err_out, "Field '%s' value '%s' not bool",
498	                             s->fields[i].name, val);
499	                    return false;
500	                }
501	                break;
502	            default:
503	                asprintf(err_out, "Unsupported field type");
504	                return false;
505	        }
506	    }
507	    return true;
508	}
