1	/*
2	 * StreamScoop Utility Lake – storage.c
3	 *
4	 * Storage writer component: subscribes to RECORD_INGESTED events on the
5	 * internal event-bus and persists rows into an on-disk SQLite “lake”.
6	 * Databases are partitioned by UTC date (YYYY/MM/DD/stream.db) to avoid
7	 * pathological file growth while keeping retrieval simple.
8	 *
9	 * This module is thread-safe, non-blocking (writes occur on an async worker
10	 * thread), and resilient to network partitions or I/O hiccups.  Errors are
11	 * surfaced via the event bus so that operators can inspect them in the
12	 * dashboard without digging through logs.
13	 *
14	 * Author: StreamScoop OSS Team
15	 * License: MIT
16	 */
