57	/* internal message pushed onto the writer queue */
58	typedef struct writer_msg {
59	    record_t   *rec;   /* ownership transferred; freed by worker           */
60	    bool        flush; /* true = explicit flush (timer/exit), rec == NULL  */
61	} writer_msg_t;
62	
63	/* lock-free ring buffer queue for producer → consumer hand-off */
64	typedef struct writer_queue {
65	    writer_msg_t      *buf;
66	    size_t             cap;
67	    atomic_size_t      head;
68	    atomic_size_t      tail;
69	} writer_queue_t;
70	
71	/* storage context – live for entire process lifetime */
72	typedef struct storage_ctx {
73	    pthread_t          worker;
74	    pthread_mutex_t    db_mtx;        /* protect SQLite connection */
75	    sqlite3           *db;            /* current open database     */
76	    char               db_path[PATH_MAX_LEN];
77	    int64_t            db_date_key;   /* YYYYMMDD corresponding to db_path */
78	    sqlite3_stmt      *insert_stmt;
79	    writer_queue_t     q;
80	    volatile bool      stop;
81	    volatile bool      running;
82	    storage_cfg_t      cfg;           /* copy of user settings     */
83	} storage_ctx_t;
