108	/* ------------------------------------------------------------------------- */
109	/*                        Event-bus subscription callback                    */
110	/* ------------------------------------------------------------------------- */
111	
112	static void
113	bus_on_record_ingested(const event_t *ev, void *udata)
114	{
115	    (void)udata;
116	
117	    if (ev->type != EVT_RECORD_INGESTED)
118	        return;
119	
120	    /* copy the record so that producer can free its own instance */
121	    record_t *dup = record_clone(ev->payload.record);
122	    if (!dup) {
123	        log_error("storage: failed to clone record – OOM");
124	        return;
125	    }
126	
127	    writer_msg_t msg = {.rec = dup, .flush = false};
128	    if (!queue_push(&G_CTX.q, msg)) {
129	        log_error("storage: writer queue overflow – dropping record");
130	        writer_cleanup_record(dup);
131	        return;
132	    }
133	}
