135	/* ------------------------------------------------------------------------- */
136	/*                       Public interface implementation                     */
137	/* ------------------------------------------------------------------------- */
138	
139	bool
140	storage_init(const storage_cfg_t *user_cfg)
141	{
142	    memset(&G_CTX, 0, sizeof(G_CTX));
143	
144	    /* copy config (caller may free its memory) */
145	    if (user_cfg)
146	        G_CTX.cfg = *user_cfg;
147	    else
148	        storage_cfg_set_defaults(&G_CTX.cfg);
149	
150	    queue_init(&G_CTX.q, G_CTX.cfg.queue_capacity);
151	
152	    pthread_mutex_init(&G_CTX.db_mtx, NULL);
153	
154	    /* open initial database (current UTC date) */
155	    int64_t today = yyyymmdd_utc(time(NULL));
156	    if (!writer_init_db(&G_CTX, today))
157	        return false;
158	
159	    /* subscribe to event bus */
160	    event_bus_subscribe(EVT_RECORD_INGESTED, bus_on_record_ingested, NULL);
161	
162	    /* spawn writer worker */
163	    G_CTX.stop = false;
164	    if (pthread_create(&G_CTX.worker, NULL, writer_thread, &G_CTX) != 0) {
165	        log_error("storage: failed to spawn writer thread: %s", strerror(errno));
166	        return false;
167	    }
168	    G_CTX.running = true;
169	
170	    log_info("storage: initialized – DB: %s", G_CTX.db_path);
171	    return true;
172	}
173	
174	void
175	storage_shutdown(void)
176	{
177	    if (!G_CTX.running)
178	        return;
179	
180	    /* tell worker to stop and wake it up */
181	    G_CTX.stop = true;
182	    queue_push(&G_CTX.q, (writer_msg_t){.flush = true, .rec = NULL});
183	
184	    pthread_join(G_CTX.worker, NULL);
185	    G_CTX.running = false;
186	
187	    event_bus_unsubscribe(EVT_RECORD_INGESTED, bus_on_record_ingested, NULL);
188	
189	    pthread_mutex_lock(&G_CTX.db_mtx);
190	    if (G_CTX.insert_stmt) {
191	        sqlite3_finalize(G_CTX.insert_stmt);
192	        G_CTX.insert_stmt = NULL;
193	    }
194	    if (G_CTX.db) {
195	        sqlite3_close_v2(G_CTX.db);
196	        G_CTX.db = NULL;
197	    }
198	    pthread_mutex_unlock(&G_CTX.db_mtx);
199	    pthread_mutex_destroy(&G_CTX.db_mtx);
200	
201	    free(G_CTX.q.buf);
202	
203	    log_info("storage: shutdown complete");
204	}
