206	/* ------------------------------------------------------------------------- */
207	/*                             Writer thread                                 */
208	/* ------------------------------------------------------------------------- */
209	
210	static void *
211	writer_thread(void *opaque)
212	{
213	    storage_ctx_t *ctx = opaque;
214	    const int flush_interval_ns =
215	        STORAGE_FLUSH_INTERVAL_MS * 1000000; /* ms → ns */
216	    struct timespec next_flush = {0};
217	
218	    /* pre-allocate batch buffer */
219	    record_t *batch[STORAGE_BATCH_SIZE];
220	    size_t    batch_sz = 0;
221	
222	    /* initial flush time */
223	    clock_gettime(CLOCK_REALTIME, &next_flush);
224	    next_flush.tv_nsec += flush_interval_ns;
225	
226	    while (!ctx->stop || atomic_load(&ctx->q.head) != atomic_load(&ctx->q.tail))
227	    {
228	        writer_msg_t msg;
229	        bool have_msg = queue_pop(&ctx->q, &msg);
230	
231	        if (!have_msg) {
232	            /* Wait until next flush or new message */
233	            struct timespec now;
234	            clock_gettime(CLOCK_REALTIME, &now);
235	
236	            bool timeout =
237	                (now.tv_sec  > next_flush.tv_sec) ||
238	                (now.tv_sec == next_flush.tv_sec && now.tv_nsec >= next_flush.tv_nsec);
239	
240	            if (timeout && batch_sz) {
241	                writer_exec_batch(ctx, batch, batch_sz);
242	                batch_sz = 0;
243	            }
244	
245	            /* small sleep to avoid busy-spin */
246	            struct timespec ts = {.tv_sec = 0, .tv_nsec = 25000000}; /* 25ms */
247	            nanosleep(&ts, NULL);
248	            continue;
249	        }
250	
251	        if (msg.flush && !msg.rec) {
252	            /* flush signal */
253	            if (batch_sz) {
254	                writer_exec_batch(ctx, batch, batch_sz);
255	                batch_sz = 0;
256	            }
257	            continue;
258	        }
259	
260	        /* rotate DB if date changed */
261	        int64_t date_key = yyyymmdd_utc(msg.rec->timestamp);
262	        if (!writer_rotate_if_needed(ctx, date_key)) {
263	            log_error("storage: failed to rotate/open db – dropping record");
264	            writer_cleanup_record(msg.rec);
265	            continue;
266	        }
267	
268	        /* add to batch */
269	        batch[batch_sz++] = msg.rec;
270	
271	        if (batch_sz >= STORAGE_BATCH_SIZE) {
272	            writer_exec_batch(ctx, batch, batch_sz);
273	            batch_sz = 0;
274	        }
275	
276	        /* update next flush */
277	        clock_gettime(CLOCK_REALTIME, &next_flush);
278	        next_flush.tv_nsec += flush_interval_ns;
279	        if (next_flush.tv_nsec >= NANO_PER_SEC) {
280	            next_flush.tv_sec  += 1;
281	            next_flush.tv_nsec -= NANO_PER_SEC;
282	        }
283	    }
284	
285	    /* final flush */
286	    if (batch_sz)
287	        writer_exec_batch(ctx, batch, batch_sz);
288	
289	    return NULL;
290	}
