292	/* ------------------------------------------------------------------------- */
293	/*                              SQLite helpers                               */
294	/* ------------------------------------------------------------------------- */
295	
296	/* Ensure directory and open/prepare database */
297	static bool
298	writer_init_db(storage_ctx_t *ctx, int64_t date_key)
299	{
300	    /* build directory path: base/YYYY/MM/DD */
301	    struct tm tm = {
302	        .tm_year = (int)(date_key / 10000) - 1900,
303	        .tm_mon  = ((date_key / 100) % 100) - 1,
304	        .tm_mday = (int)(date_key % 100),
305	        .tm_hour = 0
306	    };
307	    char dir_path[PATH_MAX_LEN];
308	    snprintf(dir_path, sizeof(dir_path), "%s/%04d/%02d/%02d",
309	             ctx->cfg.base_dir,
310	             tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday);
311	
312	    if (mkdir_p(dir_path, 0755) < 0) {
313	        log_error("storage: mkdir_p(%s) failed: %s", dir_path, strerror(errno));
314	        return false;
315	    }
316	
317	    snprintf(ctx->db_path, sizeof(ctx->db_path), "%s/%s", dir_path, DB_FILE_NAME);
318	
319	    /* open SQLite connection */
320	    pthread_mutex_lock(&ctx->db_mtx);
321	    if (ctx->db) {
322	        sqlite3_close_v2(ctx->db);
323	        ctx->db = NULL;
324	    }
325	
326	    int rc = sqlite3_open_v2(ctx->db_path, &ctx->db,
327	                             SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE |
328	                             SQLITE_OPEN_FULLMUTEX, NULL);
329	
330	    if (rc != SQLITE_OK) {
331	        log_error("storage: sqlite open failed: %s", sqlite3_errmsg(ctx->db));
332	        pthread_mutex_unlock(&ctx->db_mtx);
333	        return false;
334	    }
335	
336	    /* pragma tune-ups for embedded/edge workload */
337	    char *errmsg = NULL;
338	    sqlite3_exec(ctx->db, "PRAGMA journal_mode=WAL;", NULL, NULL, NULL);
339	    sqlite3_exec(ctx->db, "PRAGMA synchronous=NORMAL;", NULL, NULL, NULL);
340	    sqlite3_exec(ctx->db, "PRAGMA busy_timeout=5000;", NULL, NULL, NULL);
341	
342	    /* create table if not exists */
343	    const char *DDL =
344	        "CREATE TABLE IF NOT EXISTS stream_records ("
345	        "    id INTEGER PRIMARY KEY AUTOINCREMENT,"
346	        "    ts INTEGER NOT NULL,"
347	        "    raw TEXT NOT NULL,"
348	        "    valid INTEGER NOT NULL,"
349	        "    error TEXT,"
350	        "    inserted_at DATETIME DEFAULT CURRENT_TIMESTAMP"
351	        ");"
352	        "CREATE INDEX IF NOT EXISTS idx_stream_ts ON stream_records(ts);";
353	
354	    rc = sqlite3_exec(ctx->db, DDL, NULL, NULL, &errmsg);
355	    if (rc != SQLITE_OK) {
356	        log_error("storage: failed to create table: %s", errmsg);
357	        sqlite3_free(errmsg);
358	        pthread_mutex_unlock(&ctx->db_mtx);
359	        return false;
360	    }
361	
362	    /* prepare insert statement */
363	    if (!writer_prepare_stmt(ctx)) {
364	        pthread_mutex_unlock(&ctx->db_mtx);
365	        return false;
366	    }
367	
368	    ctx->db_date_key = date_key;
369	
370	    pthread_mutex_unlock(&ctx->db_mtx);
371	    return true;
372	}
373	
374	static bool
375	writer_prepare_stmt(storage_ctx_t *ctx)
376	{
377	    if (ctx->insert_stmt) {
378	        sqlite3_finalize(ctx->insert_stmt);
379	        ctx->insert_stmt = NULL;
380	    }
381	
382	    const char *SQL =
383	        "INSERT INTO stream_records (ts, raw, valid, error) "
384	        "VALUES (?1, ?2, ?3, ?4);";
385	    int rc = sqlite3_prepare_v2(ctx->db, SQL, -1, &ctx->insert_stmt, NULL);
386	    if (rc != SQLITE_OK) {
387	        log_error("storage: prepare failed: %s", sqlite3_errmsg(ctx->db));
388	        return false;
389	    }
390	    return true;
391	}
392	
393	/* rotate db if needed */
394	static bool
395	writer_rotate_if_needed(storage_ctx_t *ctx, int64_t date_key)
396	{
397	    if (date_key == ctx->db_date_key)
398	        return true;
399	    return writer_init_db(ctx, date_key);
400	}
401	
402	/* execute batch insert inside single transaction */
403	static bool
404	writer_exec_batch(storage_ctx_t *ctx, record_t **batch, size_t count)
405	{
406	    if (!count)
407	        return true;
408	
409	    pthread_mutex_lock(&ctx->db_mtx);
410	
411	    char *errmsg = NULL;
412	    int rc = sqlite3_exec(ctx->db, "BEGIN TRANSACTION;", NULL, NULL, &errmsg);
413	    if (rc != SQLITE_OK) {
414	        log_error("storage: begin tx failed: %s", errmsg);
415	        sqlite3_free(errmsg);
416	        pthread_mutex_unlock(&ctx->db_mtx);
417	        goto cleanup;
418	    }
419	
420	    for (size_t i = 0; i < count; ++i) {
421	        record_t *r = batch[i];
422	        sqlite3_reset(ctx->insert_stmt);
423	        sqlite3_bind_int64(ctx->insert_stmt, 1, (sqlite3_int64)r->timestamp);
424	        sqlite3_bind_text(ctx->insert_stmt, 2, r->raw, -1, SQLITE_STATIC);
425	        sqlite3_bind_int(ctx->insert_stmt, 3, r->valid ? 1 : 0);
426	        if (r->valid)
427	            sqlite3_bind_null(ctx->insert_stmt, 4);
428	        else
429	            sqlite3_bind_text(ctx->insert_stmt, 4,
430	                              r->error ? r->error : "unknown", -1, SQLITE_STATIC);
431	
432	        rc = sqlite3_step(ctx->insert_stmt);
433	        if (rc != SQLITE_DONE) {
434	            log_error("storage: insert failed: %s", sqlite3_errmsg(ctx->db));
435	            break;
436	        }
437	    }
438	
439	    if (rc == SQLITE_DONE) {
440	        sqlite3_exec(ctx->db, "COMMIT;", NULL, NULL, NULL);
441	    } else {
442	        sqlite3_exec(ctx->db, "ROLLBACK;", NULL, NULL, NULL);
443	    }
444	
445	    pthread_mutex_unlock(&ctx->db_mtx);
446	
447	cleanup:
448	    for (size_t i = 0; i < count; ++i)
449	        writer_cleanup_record(batch[i]);
450	    return rc == SQLITE_DONE;
451	}
