464	static int64_t
465	yyyymmdd_utc(time_t epoch)
466	{
467	    struct tm tm;
468	    gmtime_r(&epoch, &tm);
469	    return (int64_t)(tm.tm_year + 1900) * 10000 +
470	           (int64_t)(tm.tm_mon + 1) * 100 +
471	           (int64_t)tm.tm_mday;
472	}
473	
474	/* recursively create path */
475	static int
476	mkdir_p(const char *path, mode_t mode)
477	{
478	    char tmp[PATH_MAX_LEN];
479	    char *p = NULL;
480	    size_t len;
481	
482	    if (!path || !*path)
483	        return -1;
484	
485	    len = strnlen(path, sizeof(tmp));
486	    if (len >= sizeof(tmp)) {
487	        errno = ENAMETOOLONG;
488	        return -1;
489	    }
490	
491	    strncpy(tmp, path, sizeof(tmp));
492	
493	    /* iterate over string and create directories */
494	    for (p = tmp + 1; *p; ++p) {
495	        if (*p == '/') {
496	            *p = '\0';
497	            if (mkdir(tmp, mode) < 0 && errno != EEXIST)
498	                return -1;
499	            *p = '/';
500	        }
501	    }
502	    if (mkdir(tmp, mode) < 0 && errno != EEXIST)
503	        return -1;
504	    return 0;
505	}
