507	/* ------------------------------------------------------------------------- */
508	/*                        Lock-free ring buffer queue                        */
509	/* ------------------------------------------------------------------------- */
510	
511	static void
512	queue_init(writer_queue_t *q, size_t capacity)
513	{
514	    /* make capacity power-of-two for modulo trick */
515	    size_t cap_pow2 = 1;
516	    while (cap_pow2 < capacity)
517	        cap_pow2 <<= 1;
518	    q->cap = cap_pow2;
519	    q->buf = calloc(q->cap, sizeof(writer_msg_t));
520	    atomic_init(&q->head, 0);
521	    atomic_init(&q->tail, 0);
522	}
523	
524	/* returns false on overflow */
525	static bool
526	queue_push(writer_queue_t *q, writer_msg_t msg)
527	{
528	    size_t head = atomic_load_explicit(&q->head, memory_order_relaxed);
529	    size_t next = (head + 1) & (q->cap - 1);
530	
531	    if (next == atomic_load_explicit(&q->tail, memory_order_acquire))
532	        return false; /* full */
533	
534	    q->buf[head] = msg;
535	    atomic_store_explicit(&q->head, next, memory_order_release);
536	    return true;
537	}
538	
539	/* returns false if empty */
540	static bool
541	queue_pop(writer_queue_t *q, writer_msg_t *out)
542	{
543	    size_t tail = atomic_load_explicit(&q->tail, memory_order_relaxed);
544	    if (tail == atomic_load_explicit(&q->head, memory_order_acquire))
545	        return false; /* empty */
546	
547	    *out = q->buf[tail];
548	    atomic_store_explicit(&q->tail,
549	                          (tail + 1) & (q->cap - 1),
550	                          memory_order_release);
551	    return true;
552	}
