32	/* ---------------------------------------------------------------------------
33	 * External (opaque) event-bus API – Declared here so the module can compile.
34	 * The real definitions live in the core eventbus component.
35	 * --------------------------------------------------------------------------- */
36	typedef enum
37	{
38	    EVENT_RECORD_VALID = 1,   /* payload: size_t *bytes_read */
39	    EVENT_RECORD_INVALID,     /* payload: const char *error_msg (null-terminated) */
40	    EVENT_PIPELINE_STOPPED    /* payload: NULL */
41	} event_type_t;
42	
43	typedef struct event_s
44	{
45	    event_type_t type;
46	    const void  *payload;
47	    size_t       payload_len;  /* Length in bytes of payload                         */
48	} event_t;
49	
50	typedef void (*event_cb_t)(const event_t *ev, void *user_data);
51	
52	extern int  event_bus_subscribe  (event_type_t type, event_cb_t cb, void *user_data);
53	extern int  event_bus_unsubscribe(event_type_t type, event_cb_t cb, void *user_data);
54	
55	/* ---------------------------------------------------------------------------
56	 * Public API of this compilation unit.
57	 * --------------------------------------------------------------------------- */
58	int  ui_start(void);   /* Launch UI thread & subscribe to events */
59	void ui_stop (void);   /* Gracefully tear down                    */
60	
61	/* ---------------------------------------------------------------------------
62	 * Internal structures.
63	 * --------------------------------------------------------------------------- */
64	/* Mutable stats shared between event callback and UI thread */
65	typedef struct
66	{
67	    atomic_ullong total_records;
68	    atomic_ullong valid_records;
69	    atomic_ullong invalid_records;
70	    atomic_ullong bytes_read;
71	
72	    time_t        start_ts;
73	
74	    char          last_error[256];
75	    pthread_mutex_t err_mtx;
76	} ui_stats_t;
77	
78	static ui_stats_t    g_stats = {0};
79	static pthread_t     g_ui_thread;
80	static atomic_bool   g_running = ATOMIC_VAR_INIT(false);
81	
82	/* ---------------------------------------------------------------------------
83	 * Forward declarations.
84	 * --------------------------------------------------------------------------- */
85	static void *ui_thread_fn(void *unused);
86	static void  ui_handle_event(const event_t *ev, void *user_data);
87	static void  install_signal_handlers(void);
88	static void  sigwinch_handler(int signo);
89	
90	/* ---------------------------------------------------------------------------
91	 * Implementation.
92	 * --------------------------------------------------------------------------- */
93	static inline uint64_t atomic_load_u64(const atomic_ullong *v)
94	{
95	    return atomic_load_explicit(v, memory_order_relaxed);
96	}
97	
98	/* Subscribe + launch ncurses UI thread */
99	int ui_start(void)
100	{
101	    if (atomic_exchange(&g_running, true))
102	        return 0; /* Already running */
103	
104	    memset(&g_stats, 0, sizeof(g_stats));
105	    (void)pthread_mutex_init(&g_stats.err_mtx, NULL);
106	    g_stats.start_ts = time(NULL);
107	
108	    if (event_bus_subscribe(EVENT_RECORD_VALID,   ui_handle_event, NULL) != 0 ||
109	        event_bus_subscribe(EVENT_RECORD_INVALID, ui_handle_event, NULL) != 0 ||
110	        event_bus_subscribe(EVENT_PIPELINE_STOPPED, ui_handle_event, NULL) != 0)
111	    {
112	        fprintf(stderr, "ui: failed to subscribe to event bus\n");
113	        atomic_store(&g_running, false);
114	        return -1;
115	    }
116	
117	    if (pthread_create(&g_ui_thread, NULL, ui_thread_fn, NULL) != 0)
118	    {
119	        perror("ui: pthread_create");
120	        atomic_store(&g_running, false);
121	        return -1;
122	    }
123	
124	    return 0;
125	}
126	
127	/* Cancel UI thread, unsubscribe & cleanup */
128	void ui_stop(void)
129	{
130	    if (!atomic_exchange(&g_running, false))
131	        return; /* Already stopped */
132	
133	    /* Let UI thread know */
134	    pthread_join(g_ui_thread, NULL);
135	
136	    event_bus_unsubscribe(EVENT_RECORD_VALID,   ui_handle_event, NULL);
137	    event_bus_unsubscribe(EVENT_RECORD_INVALID, ui_handle_event, NULL);
138	    event_bus_unsubscribe(EVENT_PIPELINE_STOPPED, ui_handle_event, NULL);
139	
140	    pthread_mutex_destroy(&g_stats.err_mtx);
141	}
142	
143	/* ---------------------------------------------------------------------------
144	 * Event-handler updates shared statistics.
145	 * --------------------------------------------------------------------------- */
146	static void ui_handle_event(const event_t *ev, void *user_data)
147	{
148	    (void)user_data;
149	
150	    switch (ev->type)
151	    {
152	        case EVENT_RECORD_VALID:
153	            atomic_fetch_add_explicit(&g_stats.valid_records, 1, memory_order_relaxed);
154	            atomic_fetch_add_explicit(&g_stats.total_records, 1, memory_order_relaxed);
155	
156	            if (ev->payload && ev->payload_len == sizeof(size_t))
157	                atomic_fetch_add_explicit(&g_stats.bytes_read,
158	                                           *(const size_t *)ev->payload,
159	                                           memory_order_relaxed);
160	            break;
161	
162	        case EVENT_RECORD_INVALID:
163	            atomic_fetch_add_explicit(&g_stats.invalid_records, 1, memory_order_relaxed);
164	            atomic_fetch_add_explicit(&g_stats.total_records, 1, memory_order_relaxed);
165	
166	            if (ev->payload && ev->payload_len > 0)
167	            {
168	                pthread_mutex_lock(&g_stats.err_mtx);
169	                size_t n = ev->payload_len;
170	                if (n > sizeof(g_stats.last_error) - 1)
171	                    n = sizeof(g_stats.last_error) - 1;
172	                memcpy(g_stats.last_error, ev->payload, n);
173	                g_stats.last_error[n] = '\0';
174	                pthread_mutex_unlock(&g_stats.err_mtx);
175	            }
176	            break;
177	
178	        case EVENT_PIPELINE_STOPPED:
179	            /* Mark running false so UI thread will exit */
180	            atomic_store(&g_running, false);
181	            break;
182	
183	        default:
184	            /* Unknown event – ignore */
185	            break;
186	    }
187	}
188	
189	/* ---------------------------------------------------------------------------
190	 * Ncurses UI thread implementation.
191	 * --------------------------------------------------------------------------- */
192	static void *ui_thread_fn(void *unused)
193	{
194	    (void)unused;
195	    setlocale(LC_ALL, ""); /* Enable UTF-8 */
196	
197	    /* Init curses */
198	    initscr();
199	    cbreak();
200	    noecho();
201	    nodelay(stdscr, TRUE);  /* Non-blocking getch() */
202	    keypad(stdscr, TRUE);   /* Enable F-keys */
203	    curs_set(FALSE);
204	
205	    install_signal_handlers();
206	
207	    const struct timespec sleep_dur = { .tv_sec = 0, .tv_nsec = 250 * 1000 * 1000 }; /* 250ms */
208	
209	    while (atomic_load(&g_running))
210	    {
211	        /* Handle user key-strokes */
212	        int ch;
213	        while ((ch = getch()) != ERR)
214	        {
215	            if (ch == 'q' || ch == 'Q')
216	            {
217	                atomic_store(&g_running, false);
218	                break;
219	            }
220	        }
221	
222	        /* Draw UI */
223	        erase();
224	
225	        time_t now_ts = time(NULL);
226	        double elapsed = difftime(now_ts, g_stats.start_ts);
227	        if (elapsed <= 0)
228	            elapsed = 1.0;
229	
230	        uint64_t total   = atomic_load_u64(&g_stats.total_records);
231	        uint64_t valid   = atomic_load_u64(&g_stats.valid_records);
232	        uint64_t invalid = atomic_load_u64(&g_stats.invalid_records);
233	        uint64_t bytes   = atomic_load_u64(&g_stats.bytes_read);
234	
235	        double rec_per_sec  = total  / elapsed;
236	        double mb_per_sec   = (bytes / (1024.0*1024.0)) / elapsed;
237	
238	        mvprintw(0, 2, "StreamScoop Utility Lake – Live Dashboard (press 'q' to quit)");
239	        mvhline(1, 0, ACS_HLINE, COLS);
240	
241	        mvprintw(3, 4, "Uptime:           %8.1f s", elapsed);
242	        mvprintw(4, 4, "Records processed:%8" PRIu64, total);
243	        mvprintw(5, 4, "  ✓ Valid:        %8" PRIu64, valid);
244	        mvprintw(6, 4, "  ✗ Invalid:      %8" PRIu64, invalid);
245	
246	        mvprintw(8, 4, "Throughput:       %8.1f rec/s", rec_per_sec);
247	        mvprintw(9, 4, "Data rate:        %8.2f MiB/s", mb_per_sec);
248	
249	        pthread_mutex_lock(&g_stats.err_mtx);
250	        if (g_stats.last_error[0] != '\0')
251	            mvprintw(11, 4, "Last error: %s", g_stats.last_error);
252	        pthread_mutex_unlock(&g_stats.err_mtx);
253	
254	        /* Footer */
255	        mvhline(LINES - 2, 0, ACS_HLINE, COLS);
256	        mvprintw(LINES - 1, 2, "Press 'q' to exit dashboard");
257	
258	        refresh();
259	
260	        nanosleep(&sleep_dur, NULL);
261	    }
262	
263	    /* Tear down */
264	    endwin();
265	    return NULL;
266	}
